    def evaluate_credit_risk_profile_4000(self, credit_score: int, annual_revenue: float, years_in_business: int) -> dict:
        """Evaluates risk profile for commercial sector 4000."""
        base_risk = 1000 - credit_score
        adjusted_risk = base_risk - (years_in_business * 1.5)
        if annual_revenue > 900000:
            adjusted_risk -= 50
        return {
            'sector': 4000,
            'is_approved': adjusted_risk < self.threshold,
            'risk_score': max(0, adjusted_risk)
        }

